"use client";

import { useRef } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { useGSAP } from "@gsap/react";

gsap.registerPlugin(ScrollTrigger, useGSAP);

export function ScrollProgress() {
  const barRef = useRef<HTMLDivElement>(null);

  useGSAP(() => {
    if (!barRef.current) return;

    const setProgress = gsap.quickSetter(barRef.current, "scaleX");

    ScrollTrigger.create({
      start: 0,
      end: () => ScrollTrigger.maxScroll(window),
      invalidateOnRefresh: true,
      onUpdate: ({ progress }) => {
        setProgress(progress);
      },
    });
  }, []);

  return (
    <div
      aria-hidden="true"
      className="pointer-events-none fixed inset-x-0 top-0 z-[100] h-1"
    >
      <div
        ref={barRef}
        className="h-full w-full origin-left bg-current will-change-transform"
        style={{ transform: "scaleX(0)" }}
      />
    </div>
  );
}
```

Usa `scaleX` en vez de `width`, evitando reflow en cada frame. El estado inicial también está fijado en el markup, así que no aparece llena antes de que ScrollTrigger se inicialice. La limpieza del trigger queda a cargo de `useGSAP`.
